# Entry points and older comparison pages point to the expanded directory.
for path in ['guides/index.html','blog/index.html','hair-services-pittsburgh/index.html','locations/canonsburg/index.html','locations/mcmurray/index.html','locations/mt-lebanon/index.html']:
    f=R/path
