    s=f.read_text();s=re.sub(r'<!-- cc:comparison-phase-two -->.*?<!-- /cc:comparison-phase-two -->','',s,flags=re.S)
    block='<!-- cc:comparison-phase-two --><section class="archive-body"><h2>Compare local salons and appointment options</h2>'+p(a('/guides/pittsburgh-salon-alternatives','Browse 23 salon comparisons')+' · '+a('/guides/canonsburg-mcmurray-salon-alternatives','Canonsburg and McMurray alternatives')+' · '+a('/guides/salon-quote-comparison-tool','Compare your salon quotes'))+'</section><!-- /cc:comparison-phase-two -->'
    s=s.replace('</main>',block+'</main>',1) if '</main>' in s else s.replace('<footer',block+'<footer',1)
    assert block in s,path
    f.write_text(s)
